package cn.fuzhu.toolkit.modules;
import cn.fuzhu.toolkit.FuzhuToolkitPlugin; import cn.fuzhu.toolkit.module.AbstractModule; import org.bukkit.command.*; import org.bukkit.entity.Player; import org.bukkit.configuration.file.YamlConfiguration; import java.io.*;
public class HomeModule extends AbstractModule {private File f;private YamlConfiguration c;public HomeModule(FuzhuToolkitPlugin p){super(p);config=p.moduleConfig(id());f=new File(p.getDataFolder(),"configs/Home.yml");c=YamlConfiguration.loadConfiguration(f);}public String id(){return "Home";}public String description(){return "/sethome 与 /home 个人家";}public boolean handle(CommandSender s,String l,String[] a){Player p=ModuleUtil.player(plugin,s);if(p==null)return true;String k="homes."+p.getUniqueId();if(l.equalsIgnoreCase("sethome")){c.set(k,p.getLocation());save();plugin.msg(s,"&a家已设置。");}else if(c.isLocation(k)){p.teleport(c.getLocation(k));plugin.msg(s,"&a已回到家。");}else plugin.msg(s,"&e你还没有设置家。使用 /sethome");return true;}private void save(){try{c.save(f);}catch(IOException ignored){}}}
